// Embeds docs/agent-skill/family-app/SKILL.md (the canonical source) into
// src/lib/agent-skill/content.generated.ts so the app can serve it without runtime fs reads.
// Run: node scripts/generate-skill.mjs (also runs as part of `npm run build`).
// `--check` exits 1 if the generated file is stale.
import { readFile, writeFile } from "node:fs/promises";

const SRC = "docs/agent-skill/family-app/SKILL.md";
const OUT = "src/lib/agent-skill/content.generated.ts";

const md = await readFile(SRC, "utf8");
const ts = `// GENERATED by scripts/generate-skill.mjs from ${SRC}. Do not edit; edit the .md and re-run.
export const SKILL_SOURCE_PATH = ${JSON.stringify(SRC)};
export const SKILL_MD = ${JSON.stringify(md)};
`;

if (process.argv.includes("--check")) {
  const current = await readFile(OUT, "utf8").catch(() => "");
  if (current !== ts) {
    console.error(`[skill] ${OUT} is out of date. Run: node scripts/generate-skill.mjs`);
    process.exit(1);
  }
  console.log("[skill] up to date");
} else {
  await writeFile(OUT, ts);
  console.log(`[skill] wrote ${OUT}`);
}
